const e={"seo.purpose":"Who the discount calculator helps","seo.purpose.p1":`Shopping and seeing "20% off, plus an extra 10%, plus a coupon"? Enter the price, the discount, the extra % and the coupon to see what you'll actually pay.`,"seo.why":"Why use our discount calculator","seo.why.p1":"No step-by-step calculator work; numbers are calculated only in your browser.","seo.why.li1":'Uses the East Asian "zhe" style: 8 means pay 80%, and 85 or 8.5 both mean pay 85%',"seo.why.li2":"Stack an extra % off on top","seo.why.li3":"The coupon is taken off last; results to 2 decimal places","seo.faq":"Discount calculator FAQ","seo.faq.q1":"What does 8 zhe mean?","seo.faq.q1a":"You pay 80% of the price: 1000 at 8 zhe is 800.","seo.faq.q2":"Should I type 85 or 8.5 for 85 zhe?","seo.faq.q2a":"Either works; both are read as paying 85%.","seo.faq.q3":"Is the coupon applied first or last?","seo.faq.q3a":"The discount and extra % are applied first, then the coupon.","seo.faq.q4":"Why is it different from the checkout?","seo.faq.q4a":"Shops may round differently or have other rules; results are for reference."};export{e as default};
